files.code:
h1, h2 {
  color: teal;
}

h2 {
  font-size: 18px;
  margin-bottom: 0;
}

p {
  margin-top: 4px;
}

h1 {
  color: purple;
}

rows.code:
.button {
  display: inline-block;
  padding: 12px 20px;
  border-radius: 8px;
  background-color: royalblue;
  color: white;
  text-decoration: none;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

h1 {
  animation: fade-in 1s;
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

steps.text:
a {
  display: inline-block;
  padding: 10px 20px;
  background-color: teal;
  color: white;
  border-radius: 8px;
  text-decoration: none;
}
